#include "TextureDocument.hh"
#include "MaskPreset.hh"
#include <cassert>
#include <iostream>
int main(){using namespace bts;SceneSnapshot scene;MaterialSummary m;m.session_id=1;m.name="Effects";m.uniform_editable=true;scene.materials={m};ImportSummary imported;imported.materials={{1,"Effects"}};TextureDocument doc({},imported,scene);auto &set=doc.set(1);TextureDocument::add_mask(set,0);auto &mask=*set.layers[0].mask;MaskEffect selection,fill,levels;fill.kind=MaskEffectKind::Fill;fill.fill=.25;levels.kind=MaskEffectKind::Levels;levels.levels.id=levels.id;levels.levels.channel=2;levels.levels.output_low=1;levels.levels.output_high=0;mask.effects={selection,fill,levels};set.selected_effect=levels.id;assert(mask.value()==.75);TextureDocument::move_effect(set,-1);assert(mask.value()==.25&&mask.effects[1].id==levels.id);TextureDocument::move_effect(set,1);assert(mask.value()==.75);const auto previous=doc.to_json();TextureDocument::move_effect(set,1);assert(doc.to_json()==previous);std::vector<TextureSetBinding> bindings{{set.id,1,set.name}};assert(TextureDocument::from_json(doc.to_json(),bindings).to_json()==doc.to_json());const auto bytes=write_mask_preset(mask);const auto preset=read_mask_preset(bytes);assert(mask_effects_json(mask.effects)==mask_effects_json(preset.effects)&&preset.value()==.75);TextureDocument::paste_mask(set,set.selected_layer,preset);for(const auto &effect:mask.effects)if(effect.kind==MaskEffectKind::Levels)assert(effect.id==effect.levels.id&&effect.id!=levels.id);mask.effects[2].enabled=false;assert(mask.value()==.25);mask.effects[2].enabled=true;mask.effects[1].opacity=.5;assert(mask.value()==.875);mask.effects[2].levels.clamp=true;mask.effects[2].levels.output_high=-1;assert(mask.value()==.75);std::cout<<"Bottom-to-top Fill/Levels/color-selection, order changes, boundary no-op, eye/opacity, strict schema/preset roundtrip and copied effect identity passed\n";}
